const items = $input.all();
const events = items[0]?.json?.body || items[0]?.json || [];
const eventList = Array.isArray(events) ? events : [events];

let opens = 0, clicks = 0, bounces = 0, delivered = 0, total = eventList.length;
const bounceEmails = [];

eventList.forEach(evt => {
  const eventType = (evt.event || '').toLowerCase();
  if (eventType === 'open') opens++;
  else if (eventType === 'click') clicks++;
  else if (eventType === 'bounce' || eventType === 'dropped') {
    bounces++;
    bounceEmails.push(evt.email || '');
  }
  else if (eventType === 'delivered') delivered++;
});

return [{
  json: {
    timestamp: new Date().toISOString(),
    totalEvents: total,
    opens: opens,
    clicks: clicks,
    bounces: bounces,
    delivered: delivered,
    openRate: total > 0 ? ((opens / total) * 100).toFixed(1) + '%' : '0%',
    clickRate: total > 0 ? ((clicks / total) * 100).toFixed(1) + '%' : '0%',
    bounceRate: total > 0 ? ((bounces / total) * 100).toFixed(1) + '%' : '0%',
    hasBounces: bounces > 0,
    bounceEmails: JSON.stringify(bounceEmails)
  }
}];
